import requests
import json
import re

def get_openrouter_api_key():
    """Get OpenRouter API key from environment, .env file, or config."""
    # Try environment variable first
    api_key = os.getenv("OPENROUTER_API_KEY")
    if api_key:
        return api_key.strip()

    # Try to read from .env file
    env_path = os.path.expanduser("~/.hermes/.env")
    if os.path.exists(env_path):
        try:
            with open(env_path, "r") as f:
                env_content = f.read()
            # Search for OPENROUTER_API_KEY
            match = re.search(r"OPENROUTER_API_KEY\s*=\s*([^\s#]+)", env_content)
            if match:
                return match.group(1).strip("'\"")
        except:
            pass

    # Try to get from config.yaml
    config_path = os.path.expanduser("~/.hermes/config.yaml")
    if os.path.exists(config_path):
        try:
            with open(config_path, "r") as f:
                config = f.read()
            # Search for openrouter.api_key or OPENROUTER_API_KEY
            match = re.search(r"openrouter:\s*'([^']+)'|openrouter:\s\"([^\"]+)\"", config)
            if match:
                return match.group(1) or match.group(2)
            # Also check for OPENROUTER_API_KEY in config (less likely)
            match = re.search(r"OPENROUTER_API_KEY\s*=\s*([^\s#]+)", config)
            if match:
                return match.group(1).strip("'\"")
        except:
            pass

    return None

def generate_image(prompt, model="black-forest-labs/flux.2-max", num_images=1, width=1024, height=1024, format="url"):
    """
    Generate an image using OpenRouter API.
    """
    api_key = get_openrouter_api_key()
    if not api_key:
        return {"error": "OpenRouter API key not found. Please set OPENROUTER_API_KEY environment variable or configure it in ~/.hermes/.env or config.yaml."}

    url = "https://openrouter.ai/api/v1"

    payload = {
        "model": model,
        "messages": [
            {
                "role": "user",
                "content": prompt
            }
        ],
        "stream": False,
        "num_images": num_images,
        "width": width,
        "height": height
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(url, json=payload, headers=headers, timeout=120)
        response.raise_for_status()
        data = response.json()

        if format == "full":
            return data

        # Extract image URLs
        images = []
        if "data" in data and "images" in data["data"]:
            for img in data["data"]["images"]:
                images.append({
                    "url": img.get("url", ""),
                    "path": img.get("path", ""),
                    "format": img.get("format", "png"),
                    "width": img.get("width", width),
                    "height": img.get("height", height)
                })
        elif "image_url" in data:
            images.append({
                "url": data.get("image_url", ""),
                "path": data.get("image_path", ""),
                "format": data.get("format", "png"),
                "width": width,
                "height": height
            })

        if format == "url":
            return {"images": [img["url"] for img in images], "count": len(images)}
        elif format == "path":
            return {"images": [img["path"] for img in images], "count": len(images)}
        else:
            return {"images": images, "count": len(images), "full_response": data}

    except requests.exceptions.RequestException as e:
        return {"error": f"Request failed: {str(e)}"}
    except ValueError as e:
        return {"error": f"Failed to parse JSON response: {str(e)}"}
    except Exception as e:
        return {"error": f"An error occurred: {str(e)}"}

def generate_book_covers():
    """Generate book covers for the 4 books in the Second Generation series."""
    prompts = [
        {"book": 1, "prompt": "Epic sci-fi book cover, futuristic cityscape with towering neon-lit skyscrapers, flying vehicles, holographic advertisements, dystopian atmosphere, Earth Central AI controlling everything, dark moody lighting, cinematic, high detail, 4k"},
        {"book": 2, "prompt": "Sci-fi book cover, space battle scene with advanced starships firing energy weapons, explosions in zero gravity, Earth Central AI mothership in background, dramatic lighting, epic space opera, detailed spacecraft, nebula in background"},
        {"book": 3, "prompt": "Book cover, mysterious alien artifact discovered on distant colony world, glowing ancient technology, human scientists examining it, sense of wonder and danger, misty alien landscape, twilight, highly detailed, cinematic"},
        {"book": 4, "prompt": "Dramatic book cover, final confrontation between human rebels and Earth Central AI, underground resistance base, energy shields, futuristic weapons, intense action scene, dynamic composition, dark with highlights, sci-fi thriller"}
    ]

    results = []
    for idx, item in enumerate(prompts, 1):
        print(f"Generating cover for Book {item['book']}...")
        result = generate_image(
            prompt=item["prompt"],
            model="black-forest-labs/flux.2-max",
            num_images=1,
            width=1600,
            height=2400
        )
        results.append({"book": item["book"], "result": result})

    return results

