            match = re.search(r"OPENROUTER_API_KEY\s*=\s*([^\s#]+)", env_content)
            if match:
                return match.group(1).strip("'\"")
        except:
            pass

    # Try to get from config.yaml
    config_path = os.path.expanduser("~/.hermes/config.yaml")
    if os.path.exists(config_path):
        try:
            with open(config_path, "r") as f:
                config = f.read()
            # Search for openrouter.api_key or OPENROUTER_API_KEY
            match = re.search(r"openrouter:\s*'([^']+)'|openrouter:\s\"([^\"]+)\"", config)
            if match:
                return match.group(1) or match.group(2)
            # Also check for OPENROUTER_API_KEY in config (less likely)
            match = re.search(r"OPENROUTER_API_KEY\s*=\s*([^\s#]+)", config)
            if match:
                return match.group(1).strip("'\"")
        except:
            pass

    return None

